package com.madar.files;
import org.json.*;
import java.io.IOException;
import java.util.*;
final class AgentTools {
 static final String FIELDS="format quality width height start end first last angle ratio targetKb compression ocrLanguage language target translationMode musicMode musicOutput separateSpeechMusic geminiReview cutBackground cutModel pdfTextMode bitrate color padding radius flip brightness contrast saturation speed volume fadeIn fadeOut";
 static List<String> tools(String kind){String names;switch(kind){case "image":names="convert crop compress resize background rotate ocr imageBatch targetImage removebg adjust flip";break;case "video":names="convert trim compress resize mute audio music subtitles editor sound player";break;case "audio":names="subtitles convert trim sound music player";break;case "pdf":names="convert extract preview text word mergePdf imagesPdf protectPdf compressPdf layoutWord pages";break;default:names="";}List<String> out=new ArrayList<>(Arrays.asList(names.split(" ")));out.remove("");out.add("ask");return out;}
 static JSONObject schema(String kind)throws JSONException {return new JSONObject().put("type","object").put("properties",new JSONObject().put("tool",new JSONObject().put("type","string").put("enum",new JSONArray(tools(kind)))).put("fields",new JSONObject().put("type","array").put("items",new JSONObject().put("type","object").put("properties",new JSONObject().put("name",new JSONObject().put("type","string").put("enum",new JSONArray(Arrays.asList(FIELDS.split(" "))))).put("value",new JSONObject().put("type","string"))).put("required",new JSONArray(Arrays.asList("name","value"))).put("additionalProperties",false))).put("message",new JSONObject().put("type","string"))).put("required",new JSONArray(Arrays.asList("tool","fields","message"))).put("additionalProperties",false);}
 static JSONObject validate(JSONObject plan,String kind)throws Exception {if(!tools(kind).contains(plan.getString("tool")))throw new IOException("اقترح المساعد أداة غير متاحة لهذا الملف");String message=plan.getString("message");if(message.length()>1000)throw new IOException("رد المساعد أطول من الحد");JSONArray fields=plan.getJSONArray("fields");if(fields.length()>12)throw new IOException("إعدادات المساعد كثيرة؛ اطلب عملية واحدة");Set<String> seen=new HashSet<>();for(int i=0;i<fields.length();i++){JSONObject f=fields.getJSONObject(i);String name=f.getString("name"),value=f.getString("value");if(!Arrays.asList(FIELDS.split(" ")).contains(name)||!seen.add(name)||value.length()>100||value.matches("(?s).*[\\p{Cntrl}].*"))throw new IOException("إعداد مقترح غير صالح");}return plan;}
}
